// Разбор входящего обновления Telegram: фото бланка от мастера, нажатие кнопки врача, запись клиента. Чужие чаты и пользователи отбрасываются.
const u = $json;
const list = (s) => String(s || '').split(',').map((x) => x.trim()).filter(Boolean);
const masters = list($env.RX_CHAT_IDS);      // чаты мастеров, которым разрешено слать бланки
const doctors = list($env.RX_DOCTOR_IDS);    // Telegram id врачей, которым разрешено подтверждать
const out = { kind: 'reject' };
const cb = u.callback_query;
const msg = u.message;
if (cb && cb.data) {
  const from = String(cb.from && cb.from.id || '');
  const d = String(cb.data);
  let m = /^(ok|no):(\d{1,12})$/.exec(d);
  if (m && doctors.includes(from)) return { json: { kind: 'decision', decision: m[1], rx_id: m[2], doctor: from, chat: String(cb.message && cb.message.chat && cb.message.chat.id || '') } };
  m = /^book:(\d{3,10})$/.exec(d);
  if (m) return { json: { kind: 'book', card: m[1], chat: String(cb.message && cb.message.chat && cb.message.chat.id || '') } };
  return { json: out };
}
if (msg && Array.isArray(msg.photo) && msg.photo.length) {
  const chat = String(msg.chat && msg.chat.id || '');
  if (!masters.includes(chat)) return { json: out };
  const big = msg.photo[msg.photo.length - 1];
  const m = /(?:карта|card)\s*[:№#]?\s*(\d{3,10})/i.exec(String(msg.caption || ''));
  if (!m) return { json: { kind: 'nocard', chat } };
  return { json: { kind: 'photo', chat, message_id: msg.message_id, file_id: big.file_id, card: m[1] } };
}
return { json: out };

// Запрос к локальной мультимодальной модели: фото бланка в base64 уходит только в Ollama на вашем сервере.
const buf = await this.helpers.getBinaryDataBuffer('data');
if (!buf || !buf.length) throw new Error('пустое фото');
const prompt = [
  'Это фото бумажного бланка рецепта на очки.',
  'Верни ТОЛЬКО JSON такого вида: {"rows":["OD","OS"],"columns":["SPH","CYL","AXIS"],"od":{"sph":0,"cyl":0,"axis":0},"os":{"sph":0,"cyl":0,"axis":0},"add":0,"pd":0}.',
  'rows и columns: подписи строк и столбцов таблицы в том порядке, в каком они напечатаны на бланке. OD это правый глаз, OS это левый глаз.',
  'Значения бери из ячеек строки OD для od и строки OS для os. Числа с точкой, знак + или - обязателен там, где он написан. Если значение не читается, верни null.',
  'Имена, даты, телефоны и любой другой текст не читай и не возвращай.',
].join(' ');
const body = { model: $env.OLLAMA_VL_MODEL, stream: false, format: 'json', options: { temperature: 0 }, messages: [{ role: 'user', content: prompt, images: [buf.toString('base64')] }] };
return { json: { body: JSON.stringify(body) } };

// Проверка ответа модели: привязка к якорным меткам (подписи строк и столбцов), диапазоны, шаг 0,25. Любая неясность даёт ручной ввод, а не «чисто».
const src = $('Разобрать сообщение').item.json;
const errors = [];
let r = null;
const raw = $json.message && $json.message.content;
try { r = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { errors.push('ответ модели не JSON'); }
if (!r || typeof r !== 'object') { r = {}; if (!errors.length) errors.push('пустой ответ модели'); }
const up = (a) => (Array.isArray(a) ? a.map((x) => String(x).trim().toUpperCase()) : []);
const rows = up(r.rows), cols = up(r.columns);
if (!(rows.includes('OD') && rows.includes('OS') && rows.indexOf('OD') < rows.indexOf('OS'))) errors.push('таблица не опознана по якорным меткам: нет строк OD и OS');
if (!['SPH', 'CYL', 'AXIS'].every((c) => cols.includes(c))) errors.push('таблица не опознана по якорным меткам: нет столбцов SPH, CYL, AXIS');
const num = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(String(v).replace(',', '.').replace('−', '-').replace(/\s/g, ''));
  return Number.isFinite(n) ? n : NaN;
};
const step = (v) => Math.abs(v * 4 - Math.round(v * 4)) < 1e-9;
function eye(name, o) {
  o = o || {};
  const e = { sph: num(o.sph), cyl: num(o.cyl), axis: num(o.axis) };
  if (e.sph === null || Number.isNaN(e.sph)) errors.push(name + ': sph не прочитан');
  else { if (e.sph < -20 || e.sph > 20) errors.push(name + ': sph вне диапазона'); else if (!step(e.sph)) errors.push(name + ': sph не кратен 0,25'); }
  if (e.cyl === null || Number.isNaN(e.cyl)) errors.push(name + ': cyl не прочитан');
  else { if (e.cyl < -8 || e.cyl > 8) errors.push(name + ': cyl вне диапазона'); else if (!step(e.cyl)) errors.push(name + ': cyl не кратен 0,25'); }
  if (e.cyl !== null && !Number.isNaN(e.cyl) && e.cyl !== 0) {
    if (e.axis === null || Number.isNaN(e.axis) || e.axis < 0 || e.axis > 180 || !Number.isInteger(e.axis)) errors.push(name + ': axis не прочитан или вне 0-180');
  } else if (e.axis !== null && !Number.isNaN(e.axis) && (e.axis < 0 || e.axis > 180 || !Number.isInteger(e.axis))) errors.push(name + ': axis вне 0-180');
  return e;
}
const od = eye('OD', r.od), os = eye('OS', r.os);
let add = num(r.add), pd = num(r.pd);
if (add !== null && (Number.isNaN(add) || add < 0 || add > 4 || !step(add))) { errors.push('add вне диапазона или не кратен 0,25'); add = null; }
if (pd !== null && (Number.isNaN(pd) || pd < 40 || pd > 80)) { errors.push('pd вне диапазона 40-80'); pd = null; }
if (pd === null && !errors.some((x) => x.startsWith('pd'))) errors.push('pd не прочитан');
return { json: { ok: errors.length === 0, errors, rx: { od, os, add, pd }, card: src.card, chat: src.chat, message_id: src.message_id } };

// Сравнение нового бланка с последним подтверждённым рецептом клиента. Решает код, не нейросеть. Пороги условные: подберите свои вместе с врачом.
const LIM = { sph: 1.0, cyl: 0.75, axis: 20 };
const cur = $('Проверить значения').item.json;
const rx = cur.rx;
const h = $json && $json.od_sph !== undefined && $json.od_sph !== null ? $json : null;
const n = (v) => (v === null || v === undefined ? null : Number(v));
const reasons = [];
let verdict = 'ok';
if (!h) {
  verdict = 'review';
  reasons.push('нет подтверждённой истории по этой карте: нужна проверка врача');
} else {
  const hist = { od: { sph: n(h.od_sph), cyl: n(h.od_cyl), axis: n(h.od_axis) }, os: { sph: n(h.os_sph), cyl: n(h.os_cyl), axis: n(h.os_axis) } };
  for (const [name, side] of [['OD', 'od'], ['OS', 'os']]) {
    const a = hist[side], b = rx[side];
    if (a.cyl !== null && b.cyl !== null && a.cyl !== 0 && b.cyl !== 0 && Math.sign(a.cyl) !== Math.sign(b.cyl)) reasons.push(name + ': знак цилиндра изменился (' + a.cyl + ' → ' + b.cyl + ')');
    if (a.sph !== null && b.sph !== null && Math.abs(a.sph - b.sph) > LIM.sph) reasons.push(name + ': скачок sph ' + Math.abs(a.sph - b.sph).toFixed(2) + ' дптр, порог ' + LIM.sph.toFixed(2));
    if (a.cyl !== null && b.cyl !== null && Math.abs(a.cyl - b.cyl) > LIM.cyl) reasons.push(name + ': скачок cyl ' + Math.abs(a.cyl - b.cyl).toFixed(2) + ' дптр, порог ' + LIM.cyl.toFixed(2));
    if (a.axis !== null && b.axis !== null && a.cyl && b.cyl) {
      const d = Math.abs(a.axis - b.axis); const dd = Math.min(d, 180 - d);
      if (dd > LIM.axis) reasons.push(name + ': ось сдвинулась на ' + dd + '°, порог ' + LIM.axis + '°');
    }
  }
  if (reasons.length) verdict = 'block';
}
return { json: { ...cur, verdict, reasons, has_history: !!h } };

// Карточка для врача: значения, вердикт, причины. Заказ на завод система сама не отправляет: нужна кнопка врача.
const j = $('Сравнить с историей').item.json;
const id = $json.id;
const f = (v) => (v === null || v === undefined ? '-' : (v > 0 ? '+' : v < 0 ? '−' : '') + Math.abs(v).toFixed(2).replace('.', ','));
const eye = (n, e) => n + ': SPH ' + f(e.sph) + '  CYL ' + f(e.cyl) + '  AXIS ' + (e.axis === null || e.axis === undefined ? '-' : e.axis);
const head = j.verdict === 'block' ? 'ЗАКАЗ ЗАБЛОКИРОВАН: нужно решение врача' : (j.verdict === 'review' ? 'Первая запись по карте: проверьте бланк' : 'Сходится с историей: подтвердите перед заказом');
const lines = ['Проверка рецепта, карта ' + j.card + ' (запись №' + id + ')', head, '', eye('OD (правый)', j.rx.od), eye('OS (левый)', j.rx.os), 'ADD ' + f(j.rx.add) + '  PD ' + (j.rx.pd === null ? '-' : j.rx.pd)];
if (j.reasons.length) lines.push('', 'Причины:', ...j.reasons.map((x) => '- ' + x));
lines.push('', 'Система не ставит диагноз: сверьте цифры с бумажным бланком. Подтверждение записывает рецепт в историю клиента.');
return { json: { text: lines.join('\n'), id, card: j.card, chat: j.chat, message_id: j.message_id } };

// Ответ врачу после нажатия кнопки. Если записи уже приняты другим нажатием, UPDATE ничего не вернёт.
const r = $json && $json.id ? $json : null;
let text;
if (!r) text = 'Запись уже обработана или не найдена: ничего не изменено.';
else if (r.status === 'confirmed') text = 'Рецепт по карте ' + r.card_no + ' (запись №' + r.id + ') подтверждён врачом и записан в историю. Заказ на завод отправляйте вручную.';
else text = 'Рецепт по карте ' + r.card_no + ' (запись №' + r.id + ') отклонён: в историю не записан. Заказ на завод не отправляйте, перепроверьте бланк.';
return { json: { text } };
